mapper.insert:
INSERT INTO chat_message (
    conversation_id, sender_type, sender_id, menu_id, content, created_at
) VALUES (
    #{conversationId}, #{senderType}, #{senderId}, #{menuId}, #{content}, NOW()
)

mapper.select:
SELECT message_id, conversation_id, sender_type, sender_id, menu_id, content, created_at
  FROM chat_message
 WHERE conversation_id = #{conversationId}

   AND message_id > #{afterMessageId}

 ORDER BY message_id
 LIMIT #{limit}

SELECT * FROM (
    SELECT message_id, conversation_id, sender_type, sender_id, menu_id, content, created_at
      FROM chat_message
     WHERE conversation_id = #{conversationId}
     ORDER BY message_id DESC
     LIMIT #{limit}
) recent
ORDER BY message_id

SELECT * FROM (
    SELECT m.message_id, m.conversation_id, m.sender_type, m.sender_id,
           m.menu_id, m.content, m.created_at
      FROM chat_message m
      JOIN chat_conversation c ON c.conversation_id = m.conversation_id
     WHERE 1 = 1


           AND c.user_id = #{userId}


           AND c.guest_key = #{guestKey}


     ORDER BY m.message_id DESC
     LIMIT #{limit}
) recent
ORDER BY message_id
